'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseRecord } = require('./src/parse-record.js');

test('plain fields split on commas', () => {
  assert.deepStrictEqual(parseRecord('widget,9.99,blue'), ['widget', '9.99', 'blue']);
});

test('quoted field keeps its comma', () => {
  assert.deepStrictEqual(parseRecord('"Table, oak",129.00'), ['Table, oak', '129.00']);
});

test('doubled quote inside a quoted field decodes to one literal quote', () => {
  assert.deepStrictEqual(parseRecord('"14"" monitor, LED",89.99'), ['14" monitor, LED', '89.99']);
});

test('quoted field ending in an escaped quote', () => {
  assert.deepStrictEqual(parseRecord('"she said ""ok"""'), ['she said "ok"']);
});

test('empty fields are preserved', () => {
  assert.deepStrictEqual(parseRecord('a,,b'), ['a', '', 'b']);
});

test('quoted empty field', () => {
  assert.deepStrictEqual(parseRecord('"",x'), ['', 'x']);
});

