'use strict';

// Splits one CSV record line into an array of field strings.
// Quoted fields may contain commas; a doubled double quote inside a
// quoted field decodes to one literal quote character.
function parseRecord(line) {
  const fields = [];
  let field = '';
  let inQuotes = false;
  let i = 0;
  while (i < line.length) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
    } else if (ch === '"' && field === '') {
      inQuotes = true;
      i += 1;
    } else if (ch === ',') {
      fields.push(field);
      field = '';
      i += 1;
    } else {
      field += ch;
      i += 1;
    }
  }
  fields.push(field);
  return fields;
}

module.exports = { parseRecord };
